args.content:
{
  "scenes": [
    {
      "scene_id": "S1",
      "name": "杂乱桌面现状",
      "location": "办公桌前",
      "intent": "用真实乱桌面的画面建立共鸣，不制造焦虑"
    },
    {
      "scene_id": "S2",
      "name": "三分钟三步操作",
      "location": "办公桌前俯拍 / 手部特写",
      "intent": "把三个动作演示清楚，可跟做"
    },
    {
      "scene_id": "S3",
      "name": "整理后的一件待办",
      "location": "办公桌前正拍",
      "intent": "落到『已经开始工作』的状态，收尾"
    }
  ],
  "shots": [
    {
      "shot_id": "SH-01",
      "scene": "S1",
      "description": "俯拍整张桌面，杯子、便签、耳机、线材散在键盘周围，画面略拥挤。",
      "duration_sec": 5,
      "note": "无旁白，只留环境音"
    },
    {
      "shot_id": "SH-02",
      "scene": "S1",
      "description": "正拍人物视角，视线扫过桌面，短暂停顿，接开场钩子旁白。",
      "duration_sec": 5,
      "note": "旁白：桌面越乱，注意力越碎"
    },
    {
      "shot_id": "SH-03",
      "scene": "S2",
      "description": "手部特写：把视线正前方的物品逐个挪到侧边，露出干净的工作面。",
      "duration_sec": 8,
      "note": "对应第一分钟"
    },
    {
      "shot_id": "SH-04",
      "scene": "S2",
      "description": "俯拍工作面，画面只剩电脑、水杯、笔和本子，其余物品收进侧边收纳盒。",
      "duration_sec": 8,
      "note": "对应第二分钟，可用加速剪辑"
    },
    {
      "shot_id": "SH-05",
      "scene": "S2",
      "description": "特写：便签上写下唯一一件待办，贴到显示器边角。",
      "duration_sec": 8,
      "note": "对应第三分钟"
    },
    {
      "shot_id": "SH-06",
      "scene": "S3",
      "description": "正拍人物打开文件开始敲字，桌面整洁，画面定格，结尾旁白收住。",
      "duration_sec": 11,
      "note": "旁白：三分钟一到就停手"
    }
  ]
}
